    "name": "New Mining Site",
    "location": "Region A",
    "description": "A newly established mining site for resource extraction."
}
add_site_response = requests.post("https://api.socbench.example/sites/add", json=new_site_data)
if add_site_response.status_code == 201:
    print("New mining site added successfully.")
else:
    print("Failed to add new mining site.")
    exit()

