for equipment in equipment_status:
    if equipment["status"] == "Operational":
        maintenance_schedule = {
            "equipmentId": equipment["id"],
            "schedule": "2023-11-01T10:00:00Z",
            "details": "Routine maintenance check."
        }
        maintenance_response = requests.post("https://api.socbench.example/equipment/maintenance-schedule", json=maintenance_schedule)
