inventory_response = requests.get("https://api.socbench.example/inventory/status")
if inventory_response.status_code == 200:
    inventory = inventory_response.json()
    obsolete_materials = [item for item in inventory if item.get("status") == "Obsolete"]
    for material in obsolete_materials:
        print(f"Obsolete material identified: {material['name']}.")
